  sortCheck.readTitle = "Vertrauen ist gut, Testen ist besser";
  sortCheck.checkTitle = "Algorithmen analysieren, korrigieren und anwenden";
  sortCheck.intro = "Ein Sortieralgorithmus, der bei deinem Beispiel funktioniert, kann bei anderen Daten trotzdem falsch sein. Profis prüfen ihn deshalb systematisch: mit Schreibtischtests, mit Randfällen und mit gezielt gewählten Testdaten. In dieser Einheit analysierst du fremde Algorithmen, findest logische Fehler und wendest Sortieren auf neue Probleme an.";
  sortCheck.examples = [
    { title: "Einen unbekannten Algorithmus erkennen", text: "Ein Algorithmus merkt sich mit index_klein den Index des kleinsten Werts im Bereich ab zaehler1 und tauscht ihn am Ende des Durchgangs nach vorne. Das ist Selection Sort – auch wenn die Variablen anders heißen. Achte auf die Struktur, nicht auf die Namen.", code: 'a = ["B", "F", "A", "D", "C", "E"]\nfor zaehler1 in range(len(a) - 1):\n    index_klein = zaehler1\n    for zaehler2 in range(zaehler1 + 1, len(a)):\n        if a[zaehler2] < a[index_klein]:\n            index_klein = zaehler2\n    if zaehler1 != index_klein:\n        merker = a[zaehler1]\n        a[zaehler1] = a[index_klein]\n        a[index_klein] = merker' },
    { title: "Typische logische Fehler", text: "Off-by-one: Die äußere Schleife startet bei 0 statt bei 1, dann greift range(laenge - zaehler1) zu weit. Falscher Vergleich: zahlen[j] < zahlen[zaehler1 + 1] statt zahlen[j] < zahlen[j + 1]. Falscher Tausch: Der zwischenspeicher wird nicht zurückgeschrieben. Solche Fehler erzeugen keine Fehlermeldung – nur ein falsches Ergebnis." },
    { title: "Gute Testdaten wählen", text: "Teste mindestens: ein leeres Array, ein Element, bereits sortierte Daten, umgekehrt sortierte Daten, doppelte Werte, negative Zahlen. Ein Fehler zeigt sich oft erst bei einem dieser Randfälle." },
    { title: "Umsortieren ohne Sortieren", text: "Bei einer Gewinnziehung wird zuerst der niedrigste Preis gezogen, zuletzt der Hauptpreis. Für die Anzeige „Hauptgewinn zuerst“ musst du die Losnummern nicht nach Größe sortieren, sondern ihre Reihenfolge umdrehen – die Technik aus L1.5." }
  ];
